    const chamadasEsquenta = [];
    if (hubs.length) {
      const txtEsquenta = [
        '⏰ <b>ESQUENTA DE CUPONS DAS 19H!</b> · #publi',
        '',
        'Em minutos costumam liberar os lotes das 19h (e vários cupons tipo <code>FULL</code> só funcionam para quem resgatou antes!).',
