      return {
        upserts: [
          { chave: 'auto.link_direto', valor: 'sim' },
          { chave: 'auto.publicar_direto', valor: 'sim' },
          { chave: 'selo.exigir_ref90', valor: 'nao' },
          { chave: 'publicar.plataformas', valor: 'wag' },
