function normalizarBusca(s) {
  return ' ' + String(s || '')
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim() + ' ';
}

const GRUPOS_SINONIMOS = [
  ['ps5', 'playstation 5'],
  ['gta 6', 'gta vi', 'grand theft auto 6', 'grand theft auto vi'],
  ['xbox series', 'series x', 'series s'],
  ['switch 2', 'nintendo switch 2'],
