      titulo: oferta.titulo || '',
      preco: oferta.preco || 0,
      imagem: oferta.imagem || '',
      destino_grupo: grupo,
      destino_canal: canal,
      texto_grupo: textoGrupo || '',
      texto_canal: textoCanal || '',
    },
  }];
}

