    return `${c.emoji} ${nome}${k === 'top' ? ' (até 5/dia)' : ''}`;
  });
  const canais = Object.entries(cfg.categorias).map(([k, c]) => [c, linkCanal(cfg, k)]).filter(([, l]) => l)
