  const mascC = /\bmasculino\b|\bpour\s+homme\b|\bfor\s+him\b|\bmen\b/.test(nC);
  const femH = /\bfeminino\b|\bpour\s+femme\b|\bfor\s+her\b|\bwomen\b/.test(nH);
