    aprovar: true,
    motivo: 'ok',
    concorrente: menorConcorrente,
    mediana,
    preco_de_ajustado: pDeCalibrado,
    imagem_mercado: imagemMercado,
    matches: validos.length,
  };
}

function resumirAvisoMercado(av) {
  if (!av) return '';
  if (av.motivo === 'mais_barato_mercado' && av.concorrente) {
