    const refs = linhas.filter((r) => r.fonte === 'ref90' && r.data >= agora - 7 * DIA).sort((a, b) => b.data - a.data);
    if (refs.length) { ref90 = refs[0].preco; ref90_fonte = refs[0].fonte_url; }
