    .replace(/\s*(?:[-–|•]\s*)?(?:frete\s+gr[aá]tis|envio\s+(?:imediato|full|r[aá]pido)|pronta\s+entrega|em\s+estoque|original\s+com\s+nota\s+fiscal|com\s+nota\s+fiscal|12x\s+sem\s+juros|nf-?e)\b.*$/i, '')
