      if (idx > 0 && ['de', 'da', 'do', 'das', 'dos', 'e', 'com', 'sem', 'para', 'em', 'na', 'no'].includes(low)) return low;
      return w.charAt(0).toUpperCase() + w.slice(1).toLowerCase();
