function avaliarSaude(chamadas, respostas, cfg, agora) {
  const anterior = lerEstadoSaude(cfg.saude && cfg.saude.estado);
  const problemas = problemasSaude(chamadas, respostas, cfg, agora);
  const estado = {};
  const novos = [];
  for (const p of problemas) {
